package dz.local.mealguard;
import org.junit.*;import static org.junit.Assert.*;import org.json.*;import java.time.*;import java.util.*;
public class WeeklyScheduleTest {
 JSONObject cfg;JSONArray depots;
 @Before public void setup()throws Exception{cfg=new JSONObject().put("breakfast_id",10).put("lunch_id",20).put("dinner_id",10);depots=new JSONArray();for(int id:new int[]{10,20,30})depots.put(new JSONObject().put("id",id).put("nameFR","Restaurant "+id).put("breakfast",true).put("lunch",true).put("dinner",true));}
 JSONObject change(JSONObject c,int day,int meal,int index)throws Exception{JSONObject[] selected=new JSONObject[4];selected[meal]=depots.getJSONObject(index);return WeeklySchedule.setDay(c,day,selected,depots);}
 @Test public void noRulesKeepsLegacyEveryDay()throws Exception{for(int day=1;day<=7;day++)for(int meal=1;meal<=3;meal++)assertEquals(meal==2?20:10,WeeklySchedule.restaurant(cfg,day,meal));}
 @Test public void fridayLunchUsesMealDateNotExecutionDate()throws Exception{cfg=change(cfg,5,2,2);List<Engine.Meal> plan=Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4));for(Engine.Meal m:plan)assertEquals(m.type==2?(m.day.getDayOfWeek()==DayOfWeek.FRIDAY?30:20):10,m.depot.getLong("id"));}
 @Test public void allTwentyOneCellsSupportedWithoutUniversityConstants()throws Exception{for(int day=1;day<=7;day++){JSONObject[] chosen={null,depots.getJSONObject(2),depots.getJSONObject(2),depots.getJSONObject(2)};cfg=WeeklySchedule.setDay(cfg,day,chosen,depots);}for(int day=1;day<=7;day++)for(int meal=1;meal<=3;meal++)assertEquals(30,WeeklySchedule.restaurant(cfg,day,meal));}
 @Test public void multipleDaysSurviveEditingAnotherDay()throws Exception{cfg=change(cfg,5,2,2);cfg=change(cfg,6,3,1);assertEquals(30,WeeklySchedule.restaurant(cfg,5,2));assertEquals(20,WeeklySchedule.restaurant(cfg,6,3));assertEquals(20,WeeklySchedule.restaurant(cfg,6,2));}
 @Test public void removingDayRestoresDefaultsAndRetainsOtherDays()throws Exception{cfg=change(cfg,5,2,2);cfg=change(cfg,6,3,1);cfg=WeeklySchedule.setDay(cfg,5,new JSONObject[4],depots);assertEquals(20,WeeklySchedule.restaurant(cfg,5,2));assertEquals(20,WeeklySchedule.restaurant(cfg,6,3));cfg=WeeklySchedule.setDay(cfg,6,new JSONObject[4],depots);assertFalse(cfg.has(WeeklySchedule.KEY));}
 @Test public void changedRulesInvalidateChoiceEqualityAndNamesDoNot()throws Exception{JSONObject next=change(cfg,5,2,2);assertFalse(AccountSettings.sameChoices(cfg,next));JSONObject copy=new JSONObject(next.toString());copy.getJSONObject(WeeklySchedule.KEY).getJSONObject("5").getJSONObject("2").put("name","Renamed");assertTrue(AccountSettings.sameChoices(next,copy));}
 @Test public void unavailableOverrideNeverFallsBack()throws Exception{cfg=change(cfg,5,2,2);depots.remove(2);assertThrows(Engine.Problem.class,()->Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4)));}
 @Test public void unavailableMealNeverFallsBack()throws Exception{cfg=change(cfg,5,2,2);depots.getJSONObject(2).put("lunch",false);assertThrows(Engine.Problem.class,()->Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4)));}
 @Test public void savedRuleMustOfferSelectedMeal()throws Exception{depots.getJSONObject(2).put("lunch",false);assertThrows(Engine.Problem.class,()->change(cfg,5,2,2));}
 @Test public void malformedRulesFailClosed()throws Exception{for(Object bad:new Object[]{JSONObject.NULL,"bad",new JSONArray(),new JSONObject().put("8",new JSONObject()),new JSONObject().put("5",new JSONObject().put("4",new JSONObject().put("id",30))),new JSONObject().put("5",new JSONObject().put("2",new JSONObject().put("id",0))),new JSONObject().put("5",new JSONObject().put("2",new JSONObject().put("id","30")))}){cfg.put(WeeklySchedule.KEY,bad);assertThrows(Engine.Problem.class,()->Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4)));}}
 @Test public void existingFridayDefaultReservationBlocksReplacement()throws Exception{cfg=change(cfg,5,2,2);JSONArray rows=new JSONArray().put(new JSONObject().put("id",1).put("date_reserve","2026-11-06").put("mealtype_fr","lunch").put("depot_fr","Restaurant 20"));assertThrows(Engine.Problem.class,()->Engine.plan(cfg,depots,rows,LocalDate.of(2026,11,4)));}
 @Test public void existingMatchingFridayReservationIsRecognized()throws Exception{cfg=change(cfg,5,2,2);JSONArray rows=new JSONArray().put(new JSONObject().put("id",77).put("date_reserve","2026-11-06").put("mealtype_fr","lunch").put("depot_fr","Restaurant 30"));List<Engine.Meal> p=Engine.plan(cfg,depots,rows,LocalDate.of(2026,11,4));assertEquals(77,p.get(4).existingId);assertEquals(9,p.size());}
 @Test public void weeklyMappingAcrossYearBoundary()throws Exception{cfg=change(cfg,5,2,2);List<Engine.Meal> p=Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,12,30));assertEquals(LocalDate.of(2027,1,1),p.get(4).day);assertEquals(30,p.get(4).depot.getLong("id"));}
 @Test public void saveIsCopyAndMigrationRetainsRules()throws Exception{JSONObject next=change(cfg,5,2,2);assertFalse(cfg.has(WeeklySchedule.KEY));assertEquals(30,WeeklySchedule.restaurant(AccountSettings.migrate(next),5,2));assertEquals(AccountSettings.journalKey(new JSONObject().put("student","123")),AccountSettings.journalKey(next.put("student","123")));}
 @Test public void daySummaryExposesMealAndRestaurant()throws Exception{cfg=change(cfg,5,2,2);assertTrue(WeeklySchedule.daySummary(cfg,5).contains("الغداء"));assertTrue(WeeklySchedule.daySummary(cfg,5).contains("Restaurant 30"));}
 @Test public void actualBookingUsesOverrideAndRetainsNineMealVerification()throws Exception{EngineTest fixture=new EngineTest();fixture.setup();int day=Engine.today().plusDays(1).getDayOfWeek().getValue();JSONObject[] chosen=new JSONObject[4];chosen[2]=fixture.depots.getJSONObject(0);fixture.cfg=WeeklySchedule.setDay(fixture.cfg,day,chosen,fixture.depots);EngineTest.Fake api=fixture.new Fake();List<Engine.Meal> plan=fixture.plan();assertEquals(10,plan.get(1).depot.getLong("id"));EngineTest.Memory memory=new EngineTest.Memory();Engine.apply(api,memory,plan,()->false);assertEquals(9,api.writes);assertEquals(9,api.data.length());assertEquals(0,memory.j.length());assertEquals("Dorm",api.data.getJSONObject(1).getString("depot_fr"));}
 @Test public void pendingLockSurvivesChangingRestaurantRule()throws Exception{EngineTest fixture=new EngineTest();fixture.setup();List<Engine.Meal> old=fixture.plan();EngineTest.Memory memory=new EngineTest.Memory();memory.j.put(old.get(1).key(),new JSONObject().put("state","pending").put("depot",20));JSONObject[] chosen=new JSONObject[4];chosen[2]=fixture.depots.getJSONObject(0);fixture.cfg=WeeklySchedule.setDay(fixture.cfg,old.get(1).day.getDayOfWeek().getValue(),chosen,fixture.depots);EngineTest.Fake api=fixture.new Fake();assertThrows(Engine.Problem.class,()->Engine.apply(api,memory,fixture.plan(),()->false));assertEquals(8,api.writes);assertTrue(memory.j.has(old.get(1).key()));}

 @Test public void exceptionRestaurantEnablesUnconfiguredMealThatDayOnly()throws Exception{JSONObject base=new JSONObject().put("lunch_id",20);JSONObject[] chosen=new JSONObject[4];chosen[3]=depots.getJSONObject(2);JSONObject next=WeeklySchedule.setDay(base,5,chosen,depots);assertEquals(30,WeeklySchedule.restaurant(next,5,3));assertEquals(0,WeeklySchedule.restaurant(next,4,3));assertEquals(0,WeeklySchedule.restaurant(next,5,1));assertEquals(20,WeeklySchedule.restaurant(next,5,2));assertTrue(WeeklySchedule.daySummary(next,5).contains("العشاء"));assertTrue(WeeklySchedule.daySummary(next,5).contains("Restaurant 30"));List<Engine.Meal> plan=Engine.plan(next,depots,new JSONArray(),LocalDate.of(2026,11,4));int dinners=0;for(Engine.Meal m:plan)if(m.type==3){dinners++;assertEquals(LocalDate.of(2026,11,6),m.day);assertEquals(30,m.depot.getLong("id"));}assertEquals(1,dinners);}

 @Test public void skipRuleIsStoredBySetDayReportedByRestaurantAndSummarized()throws Exception{JSONObject[] chosen=new JSONObject[4];chosen[2]=new JSONObject().put("skip",true);JSONObject next=WeeklySchedule.setDay(cfg,5,chosen,depots);assertEquals(-1,WeeklySchedule.restaurant(next,5,2));assertEquals(20,WeeklySchedule.restaurant(next,4,2));assertEquals(10,WeeklySchedule.restaurant(next,5,1));assertTrue(WeeklySchedule.daySummary(next,5).contains("غير مُختارة"));assertFalse(AccountSettings.sameChoices(cfg,next));assertTrue(WeeklySchedule.rules(next).getJSONObject("5").getJSONObject("2").optBoolean("skip"));}
 @Test public void skipRuleBlocksOnlyThatMealThatDay()throws Exception{LocalDate day=Engine.today().plusDays(1);int dw=day.getDayOfWeek().getValue();JSONObject[] chosen=new JSONObject[4];chosen[2]=new JSONObject().put("skip",true);JSONObject next=WeeklySchedule.setDay(cfg,dw,chosen,depots);List<Engine.Meal> plan=Engine.plan(next,depots,new JSONArray(),Engine.today());assertEquals(8,plan.size());for(Engine.Meal m:plan)assertFalse(m.type==2&&m.day.equals(day));}
 @Test public void skipAndRestaurantRulesReplaceEachOtherAndClearCleanly()throws Exception{cfg=change(cfg,5,2,2);JSONObject[] skipped=new JSONObject[4];skipped[2]=new JSONObject().put("skip",true);cfg=WeeklySchedule.setDay(cfg,5,skipped,depots);assertEquals(-1,WeeklySchedule.restaurant(cfg,5,2));cfg=WeeklySchedule.setDay(cfg,5,new JSONObject[]{null,null,depots.getJSONObject(1),null},depots);assertEquals(20,WeeklySchedule.restaurant(cfg,5,2));cfg=WeeklySchedule.setDay(cfg,5,new JSONObject[4],depots);assertFalse(cfg.has(WeeklySchedule.KEY));}
 @Test public void malformedSkipRulesFailClosed()throws Exception{for(Object bad:new Object[]{new JSONObject().put("skip","yes"),new JSONObject().put("id",0),new JSONObject().put("skip",false)}){cfg.put(WeeklySchedule.KEY,new JSONObject().put("5",new JSONObject().put("2",bad)));assertThrows(Engine.Problem.class,()->Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4)));}cfg.put(WeeklySchedule.KEY,new JSONObject().put("5",new JSONObject().put("2",new JSONObject().put("skip",true))));assertEquals(8,Engine.plan(cfg,depots,new JSONArray(),LocalDate.of(2026,11,4)).size());}

}
